//! Short conversation titles generated by a model.

use anyhow::{Context as _, bail};
use zp_ai::{Context, Message, Model, Models, StopReason, StreamOptions, ThinkingLevel};

const TITLE_PROMPT: &str = "You name coding conversations. Reply with a title of at most six \
                            words for the conversation that starts with the user's message. \
                            Use the message's language. No quotes, no trailing punctuation.";
/// Longest message excerpt sent for titling.
const EXCERPT_CHARS: usize = 2000;
/// Longest title kept.
const MAX_TITLE_CHARS: usize = 60;

/// The model used for titles: the cheapest priced model of `current`'s provider (titles
/// do not need a strong model), else `current` itself.
pub fn title_model(models: &Models, current: &Model) -> Model {
    models
        .models(Some(&current.provider))
        .into_iter()
        .filter(|model| model.cost.input > 0.0 && model.api == current.api)
        .min_by(|a, b| {
            (a.cost.input + a.cost.output)
                .partial_cmp(&(b.cost.input + b.cost.output))
                .unwrap_or(std::cmp::Ordering::Equal)
        })
        .unwrap_or_else(|| current.clone())
}

/// Asks `model` for a title for a conversation starting with `first_message`.
pub async fn generate_title(
    models: &Models,
    model: &Model,
    first_message: &str,
) -> anyhow::Result<String> {
    let excerpt: String = first_message.chars().take(EXCERPT_CHARS).collect();
    let context = Context {
        system_prompt: Some(TITLE_PROMPT.to_owned()),
        messages: vec![Message::user(excerpt)],
        tools: Vec::new(),
    };
    let options = StreamOptions {
        thinking: model.clamp_thinking_level(ThinkingLevel::Off),
        max_tokens: Some(256),
        // A one-off request: a cache write would not be read again.
        cache_retention: zp_ai::CacheRetention::None,
        ..StreamOptions::default()
    };
    let reply = models.complete(model, &context, options).await;
    if matches!(reply.stop_reason, StopReason::Error | StopReason::Aborted) {
        bail!(
            "title request failed: {}",
            reply.error_message.unwrap_or_default()
        );
    }
    clean_title(&reply.text()).context("the model returned an empty title")
}

/// The first non-empty line without quotes, markdown markers or trailing punctuation.
pub fn clean_title(raw: &str) -> Option<String> {
    let line = raw.lines().map(str::trim).find(|line| !line.is_empty())?;
    let line = line
        .trim_start_matches(['#', '*', '-', ' '])
        .trim_start_matches("Title:")
        .trim();
    let mut line = line;
    loop {
        let trimmed = line
            .trim_matches(|c: char| matches!(c, '"' | '\'' | '`' | '*' | '“' | '”' | '「' | '」'))
            .trim_end_matches(['.', '。', '!', '?', ':'])
            .trim();
        if trimmed == line {
            break;
        }
        line = trimmed;
    }
    if line.is_empty() {
        return None;
    }
    let mut title: String = line.chars().take(MAX_TITLE_CHARS).collect();
    if line.chars().count() > MAX_TITLE_CHARS {
        title.push('…');
    }
    Some(title)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cleans_titles() {
        assert_eq!(
            clean_title("\n\"Fix the parser bug.\"\n").as_deref(),
            Some("Fix the parser bug")
        );
        assert_eq!(
            clean_title("## Title: Refactor CLI").as_deref(),
            Some("Refactor CLI")
        );
        assert_eq!(
            clean_title("「修复解析器」。").as_deref(),
            Some("修复解析器")
        );
        assert_eq!(clean_title("  \n "), None);
        assert!(clean_title(&"x".repeat(100)).unwrap().ends_with('…'));
    }
}
